{snippet:provision-account}

runtime.database_provision:
{snippet:admin}
{snippet:label}
{snippet:account-name}
label "$STACK_DATABASE" 'the database name'
account_name "$STACK_DATABASE_USER" 'the database account'
account="$STACK_DATABASE_USER"
database="$STACK_DATABASE"
kind=database
