runtime.database_reset:
{snippet:admin}
{snippet:label}
{snippet:account-name}
{snippet:target-owned}
printf 'DROP DATABASE IF EXISTS `%s`;\nCREATE DATABASE `%s`;\n' "$STACK_DATABASE" "$STACK_DATABASE" | admin

runtime.database_clone:
{snippet:admin}
{snippet:label}
{snippet:account-name}
{snippet:target-owned}
label "$STACK_SOURCE_DATABASE" 'the source database name'
account_name "$STACK_SOURCE_DATABASE_USER" 'the source database account'
problem="$(printf "SELECT CASE
  WHEN '%s' IN ('mysql', 'information_schema', 'performance_schema', 'sys')
    OR NOT EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME = '%s')
    OR NOT EXISTS (SELECT 1 FROM mysql.db WHERE Db = '%s' AND User = '%s' AND Host = '%%')
    THEN 'the source database does not belong to its account; inspect existing state'
  ELSE '' END;\n" "$STACK_SOURCE_DATABASE" "$STACK_SOURCE_DATABASE" "$STACK_SOURCE_DATABASE" "$STACK_SOURCE_DATABASE_USER" | admin)"
[ -z "$problem" ] || refuse "$problem"
{snippet:dump}
{snippet:replay}
printf "DROP DATABASE IF EXISTS \`%s\`;\nGRANT ALL ON \`%s\`.* TO '%s'@'%%';\nCREATE DATABASE \`%s\`;\n" "$STACK_DATABASE" "$STACK_DATABASE" "$STACK_DATABASE_USER" "$STACK_DATABASE" | admin
{ dump "$STACK_SOURCE_DATABASE" || : > "$failed"; } | replay 'the source database could not be copied'

runtime.database_dump:
{snippet:admin}
{snippet:label}
{snippet:account-name}
{snippet:target-owned}
[ "$(printf "SELECT COUNT(*) FROM INFORMATION_SCHEMA.SCHEMATA WHERE SCHEMA_NAME = '%s';\n" "$STACK_DATABASE" | admin)" = 1 ] ||
  refuse 'the database does not exist; run stack up to provision it'
{snippet:dump}
dump "$STACK_DATABASE"

runtime.database_restore:
{snippet:admin}
{snippet:label}
{snippet:account-name}
{snippet:target-owned}
{snippet:replay}
printf 'CREATE DATABASE IF NOT EXISTS `%s`;\n' "$STACK_DATABASE" | admin
replay 'the dump could not be read whole'

