group: shop
runtimes:
  php: "8.4"
services:
  - {name: db, type: mysql, version: "8.4", commands: [mysql]}
  - {name: cache, type: valkey}
sites:
  - {name: app, type: laravel}

group: shop
services:
  - {name: db, type: mysql, shared: local}

snippets.admin:
set -eu
umask 077
export MYSQL_TEST_LOGIN_FILE="$STACK_DATA_DIR/no-login-path"
export MYSQL_PWD="$MYSQL_ADMIN_PASSWORD"
admin() {
  "$STACK_INSTALL_DIR/bin/mysql" --no-defaults --protocol=SOCKET --socket="$STACK_SOCKET_DIR/mysqld.sock" --user=stack_admin --batch --skip-column-names "$@"
}
refuse() {
  printf '%s\n' "$1" >&2
  exit 1
}

snippets.label:
label() {
  case "$1" in
    '' | *[!a-z0-9-]*) refuse "$2 is not a name Stack writes into SQL" ;;
  esac
}

snippets.account-name:
account_name() {
  case "$1" in
    '' | *[!a-z0-9_-]*) refuse "$2 is not a name Stack writes into SQL" ;;
  esac
}
